1.​ Open a new Google Doc, click Extensions, and click the “Apps Script” button. 
2.​ Once you are in Google Scripts, delete the existing code and add this code: 
function onOpen() { 
  DocumentApp.getUi() 
    .createMenu('cool game') 
    .addItem('Open Dialog', 'showDialog') 
    .addToUi(); 
} 

function showDialog() { 
  var html = HtmlService.createHtmlOutputFromFile('Index') 
    // if you want to change the htmls name change this 
    .setWidth(10000) 
    .setHeight(1000); 

  DocumentApp.getUi().showModalDialog(html, 'html runner'); 
} 
